import{describe,it,expect}from"vitest";import{locations,movies,btsTriviaList,galleryItems,getLocationById,getMovieById,getMoviesByLocation,getTriviaByLocation,filterMovies,filterGallery}from"../../frontend/up-filming/up-filming.js";const REQUIRED_LOCATION_FIELDS=["id","name","city","tagline","description","famousMovies","highlights","btsFact","coords","icon","colorTheme"],REQUIRED_MOVIE_FIELDS=["id","title","year","director","cast","locationIds","genre","description","btsTrivia","posterIcon","rating"],MANDATORY_LOCATION_IDS=["varanasi_ghats","taj_mahal","lucknow","agra","jhansi","prayagraj"];describe("UP Filming Locations Dataset Integrity",()=>{it("contains all 6 mandatory UP filming locations",()=>{expect(locations.length).toBe(6);const e=locations.map(e=>e.id.toLowerCase());MANDATORY_LOCATION_IDS.forEach(t=>{expect(e).toContain(t)})}),it("every location profile contains all required fields with valid types",()=>{locations.forEach((e,t)=>{REQUIRED_LOCATION_FIELDS.forEach(o=>{expect(e,`Location at index ${t} missing field ${o}`).toHaveProperty(o),"famousMovies"===o||"highlights"===o?(expect(Array.isArray(e[o])).toBe(!0),expect(e[o].length).toBeGreaterThan(0)):"coords"===o?(expect(typeof e.coords.x).toBe("number"),expect(typeof e.coords.y).toBe("number")):(expect(typeof e[o]).toBe("string"),expect(e[o].trim().length).toBeGreaterThan(0))})})}),it("all location IDs are unique",()=>{const e=locations.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Movies Dataset Integrity",()=>{it("contains at least 10 blockbuster movies filmed in UP",()=>{expect(movies.length).toBeGreaterThanOrEqual(10)}),it("every movie contains all required fields with valid types",()=>{const e=new Set(locations.map(e=>e.id));movies.forEach((t,o)=>{REQUIRED_MOVIE_FIELDS.forEach(e=>{expect(t,`Movie at index ${o} missing field ${e}`).toHaveProperty(e),"cast"===e||"locationIds"===e?(expect(Array.isArray(t[e])).toBe(!0),expect(t[e].length).toBeGreaterThan(0)):"year"===e?(expect(typeof t.year).toBe("number"),expect(t.year).toBeGreaterThan(1950)):(expect(typeof t[e]).toBe("string"),expect(t[e].trim().length).toBeGreaterThan(0))}),t.locationIds.forEach(o=>{expect(e.has(o),`Movie ${t.title} has invalid locationId ${o}`).toBe(!0)})})}),it("retrieves movie by ID correctly",()=>{const e=getMovieById("m-1");expect(e).toBeDefined(),expect(e.title).toBe("Raanjhanaa")})}),describe("BTS Trivia & Gallery Items",()=>{it("contains BTS trivia items for every mandatory location",()=>{expect(btsTriviaList.length).toBeGreaterThanOrEqual(6);const e=new Set(btsTriviaList.map(e=>e.locationId));MANDATORY_LOCATION_IDS.forEach(t=>{expect(e.has(t)).toBe(!0)})}),it("contains gallery items for locations",()=>{expect(galleryItems.length).toBeGreaterThanOrEqual(6),galleryItems.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("locationId"),expect(e).toHaveProperty("category")})})}),describe("Search & Filter Helpers",()=>{it("filters movies by search query (e.g., Raanjhanaa or Dhanush)",()=>{const e=filterMovies("Dhanush");expect(e.length).toBeGreaterThan(0),expect(e[0].title).toBe("Raanjhanaa")}),it("filters movies by location ID (e.g., lucknow)",()=>{const e=filterMovies("","lucknow");expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.locationIds).toContain("lucknow")})}),it("filters movies by genre (e.g., romance)",()=>{const e=filterMovies("","all","romance");expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.genre.toLowerCase()).toContain("romance")})}),it("filters gallery items by location and category",()=>{const e=filterGallery("varanasi_ghats","all");expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.locationId).toBe("varanasi_ghats")})}),it("retrieves movies filmed at a specific location",()=>{const e=getMoviesByLocation("taj_mahal");expect(e.length).toBeGreaterThan(0)})});